#include <bits/stdc++.h>
using namespace std;
typedef __int128 i128;

long long normalTime, priorityTime;
vector<long long> p;

// minimum cost of the interval [start, start+length) holding p[left..right)
i128 visit(long long start, long long length, int left, int right) {
    if (left == right) return normalTime;
    i128 direct = (i128)priorityTime * (right - left) * length;  // may exceed 64 bits
    if (length == 1) return direct;
    long long mid = start + length / 2;
    int split = lower_bound(p.begin() + left, p.begin() + right, mid) - p.begin();
    i128 halves = visit(start, length / 2, left, split) + visit(mid, length / 2, split, right);
    return min(direct, halves);
}

