import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static boolean hasMore() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return false;
        ptr--;
        return true;
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    // INF caps a direct cost that would overflow 64 bits; real answers stay far below it
    static final long INF = 4_000_000_000_000_000_000L;
    static long normalTime, priorityTime;
    static long[] p;

    // first index in [left, right) with p[index] >= target
    static int lowerBound(int left, int right, long target) {
        while (left < right) {
            int mid = (left + right) >>> 1;
            if (p[mid] < target) left = mid + 1;
            else right = mid;
        }
        return left;
    }

    // minimum cost of the interval [start, start+length) holding p[left..right)
    static long visit(long start, long length, int left, int right) {
        if (left == right) return normalTime;
        long count = priorityTime * (right - left);
        long direct = count <= INF / length ? count * length : INF;
        if (length == 1) return direct;
        long mid = start + length / 2;
        int split = lowerBound(left, right, mid);
        return Math.min(direct, visit(start, length / 2, left, split) + visit(mid, length / 2, split, right));
    }

    public static void main(String[] args) throws IOException {
        long n = nextLong();
        int k = nextInt();
        normalTime = nextLong();
        priorityTime = nextLong();
        p = new long[k];
        for (int i = 0; i < k; i++) p[i] = nextLong();
        Arrays.sort(p);
        System.out.println(visit(1, n, 0, k));
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"slices"
	"sort"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

// INF caps a direct cost that would overflow 64 bits; real answers stay far below it
const INF = int64(4e18)

var normalTime, priorityTime int64
var p []int64

// minimum cost of the interval [start, start+length) holding p[left:right]
func visit(start, length int64, left, right int) int64 {
	if left == right {
		return normalTime
	}
	count := priorityTime * int64(right-left)
	direct := INF
	if count <= INF/length {
		direct = count * length
	}
	if length == 1 {
		return direct
	}
	mid := start + length/2
	split := left + sort.Search(right-left, func(i int) bool { return p[left+i] >= mid })
	return min(direct, visit(start, length/2, left, split)+visit(mid, length/2, split, right))
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, k := nextInt(), int(nextInt())
	normalTime, priorityTime = nextInt(), nextInt()
	p = make([]int64, k)
	for i := range p {
		p[i] = nextInt()
	}
	slices.Sort(p)
	fmt.Println(visit(1, n, 0, k))
}
